    def _validate_sequence(self, sequence: str) -> bool:
        """Validate protein sequence"""
        valid_aa = set("ACDEFGHIKLMNPQRSTVWY")
        return all(aa in valid_aa for aa in sequence.upper())

    async def _generate_msa(self, sequence: str, mode: str) -> str:
        """Generate MSA using HHblits or JackHMMER"""
        temp_dir = tempfile.mkdtemp()
        fasta_path = os.path.join(temp_dir, "query.fasta")
        msa_path = os.path.join(temp_dir, "output.a3m")

        # Write query sequence
        with open(fasta_path, 'w') as f:
            f.write(f">query\n{sequence}\n")

        if mode == "hhblits":
            cmd = [
                "hhblits",
                "-i", fasta_path,
                "-d", os.getenv("UNICLUST_DB", "/databases/uniclust30_2018_08/uniclust30_2018_08"),
                "-oa3m", msa_path,
                "-n", "3",
                "-e", "0.001"
            ]
        else:  # jackhmmer
            cmd = [
                "jackhmmer",
                "--tblout", "/dev/null",
                "-A", msa_path,
                "-N", "5",
                "-E", "0.0001",
                fasta_path,
                os.getenv("UNIREF90_DB", "/databases/uniref90.fasta")
            ]

        try:
            result = await asyncio.create_subprocess_exec(
                *cmd,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE
            )
            stdout, stderr = await result.communicate()

            if result.returncode != 0:
                logger.error(f"MSA generation failed: {stderr.decode()}")
                raise HTTPException(status_code=500, detail="MSA generation failed")

            return msa_path
        except Exception as e:
            logger.error(f"MSA generation error: {e}")
            raise HTTPException(status_code=500, detail=f"MSA generation error: {e}")

