                    const requestData = {
                        sequence: sequence.toUpperCase(),
                        msa_mode: options.msaMode || 'auto',
                        confidence_cutoff: options.confidenceCutoff || 0.7,
                        max_iterations: options.maxIterations || 48,
                        gpu_acceleration: options.gpuAcceleration || 'auto'
