            setupPredictionWebSocket(predictionId) {
                const wsUrl = `${this.wsBase}/prediction/${predictionId}`;
                this.predictionWs = new WebSocket(wsUrl);

                this.predictionWs.onmessage = (event) => {
                    const data = JSON.parse(event.data);
